#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    int count = 0;
    int sum = 0;
    for (int i = 0; i < n; i++) {
        int sample;
        cin >> sample;
        if (sample >= 0 && sample <= 100) {
            count++;
            sum += sample;
        }
    }

    cout << "VALID SAMPLES: " << count << endl;
    cout << "TOTAL VALID SUM: " << sum << endl;
    return 0;
}

